sealed interface Violation {
    val field: String
    data class Range(override val field: String, val message: String) : Violation
    data class Missing(override val field: String) : Violation
}

class Notification {
    private val entries = mutableListOf<Violation>()
    fun add(v: Violation) { entries += v }
    val errors: List<Violation> get() = entries.toList()
    val hasErrors: Boolean get() = entries.isNotEmpty()
}

