fun validate(input: BookingRequest): Either<NonEmptyList<Violation>, Booking> = either {
    zipOrAccumulate(
        { validateSeats(input.seats) },
        { validateDate(input.date) }
    ) { seats, date -> Booking(seats, date) }
}
